from pathlib import Path


def replace_once(path: str, old: str, new: str) -> None:
    file = Path(path)
    text = file.read_text()
    if old not in text:
        raise SystemExit(f"marker missing in {path}: {old[:120]!r}")
    file.write_text(text.replace(old, new, 1))


