new_editor = '''function renderCustomRoleEditor(role: AccessRoleDefinition): string {\n  if (role.retiredAt) {\n    return `<article class="custom-role-card">\n      <div class="role-heading"><div><p class="eyebrow">Retired custom role</p><h3>${escapeHtml(role.name)}</h3></div><code>${escapeHtml(role.key)}</code></div>\n      <p class="impact clear"><strong>Retired ${escapeHtml(role.retiredAt)}</strong> · historical definition only. It cannot be edited, reactivated, or assigned to new members.</p>\n      <p class="muted">Permissions retained for audit/export history: ${role.permissions.map(escapeHtml).join(", ")}</p>\n    </article>`;\n  }\n\n  const impact =\n    role.assignmentCount === 0\n      ? '<p class="impact clear">No current tenant assignments use this role.</p>'\n      : `<div class="impact"><strong>${role.assignmentCount} current tenant assignment${role.assignmentCount === 1 ? "" : "s"} will be affected by changes:</strong><ul>${role.assignedMembers.map((member) => `<li>${escapeHtml(member)}</li>`).join("")}</ul></div>`;\n  const acknowledgement =\n    role.assignmentCount === 0\n      ? ""\n      : `<label class="ack"><input type="checkbox" name="acknowledgeAssignments" value="yes" required> I understand this change affects the current assignments listed above.</label>`;\n  const retirement =\n    role.assignmentCount === 0\n      ? `<form method="post" action="/demo/app/admin/access/roles/retire" class="retire-form"><input type="hidden" name="roleDefinitionId" value="${escapeHtml(role.id)}"><p class="muted">Retirement is terminal. The definition remains in audit/export history but cannot be assigned or edited again.</p><button class="secondary" type="submit">Retire custom role</button></form>`\n      : '<p class="muted"><strong>Retirement unavailable:</strong> remove every tenant assignment for this role first.</p>';\n  return `<article class="custom-role-card">\n    <div class="role-heading"><div><p class="eyebrow">Custom role</p><h3>${escapeHtml(role.name)}</h3></div><code>${escapeHtml(role.key)}</code></div>\n    ${impact}\n    <form method="post" action="/demo/app/admin/access/roles/update" class="role-form">\n      <input type="hidden" name="roleDefinitionId" value="${escapeHtml(role.id)}">\n      <label>Role name\n        <input name="name" required minlength="2" maxlength="80" value="${escapeHtml(role.name)}" autocomplete="off">\n      </label>\n      ${permissionFieldset(role.permissions)}\n      ${acknowledgement}\n      <button type="submit">Save custom role</button>\n    </form>\n    ${retirement}\n  </article>`;\n}\n'''
